LOOKUP={name:key for key,names in GROUPS.items() for name in names.split()}
family('dropout','Training dropout and expectation scaling','Randomly mask hidden responses during training and preserve their expected scale.','Inverted dropout divides retained responses by their keep probability. This discourages reliance on one particular activation combination; inference uses the unmasked network.','No dropout removes this source of training noise. Weight decay penalises parameter magnitude and image augmentation changes inputs; these regularisers act differently and can be combined.','A framework dropout layer handles train/eval switching and random masks. Match keep probability, mask shape, dtype and random seed for a numerical comparison. It adds no inference-time masking when disabled; it does not guarantee higher held-out accuracy.','srivastava2014,code2026')
family('crossentropy','Writer cross entropy','Penalise the network for assigning low probability to the labelled writer.','For a one-hot writer label, negative log probability is the categorical negative log likelihood. Its logit gradient is predicted probability minus the target indicator; it trains the mutually exclusive writer head.','Squared probability error changes the derivative and optimisation behaviour. Class-weighted cross entropy changes the relative cost of examples and needs a justified weighting policy. This is distinct from CTC, which marginalises unknown character alignments.','Framework cross-entropy losses normally accept raw logits and combine stable log softmax with target indexing. Feeding probabilities instead, or changing sum/mean reduction, changes the objective or gradient scale. A compiled loss may reduce overhead but is not inherently a different classifier.','gravesbook,code2026')
def classify(e):
    name=e['name']; mod=e['module']
    if name=='EstimateSlantDeg':return 'deskew'
    if name=='ClassifyImage':return 'conv'
    if name=='Conv2dForward' or name=='ConvBlockForwardTrain':return 'conv'
    if name in ['DropoutForward','DropoutBackward']:return 'dropout'
    if name=='CrossEntropyLoss':return 'crossentropy'
    if name in ['TextModelForward','EvalTextForward','AuthorModelForward','EvalAuthorForward']:return 'conv'
    if mod=='web/lineworkers.py': return 'workers'
    if mod=='web/camera.py': return 'camera'
    if mod=='timing.py': return 'timing'
    if mod=='retrace.py': return 'retrace'
    if name in LOOKUP:return LOOKUP[name]
    if mod=='curate.py':return 'curate'
    if mod.startswith('web/'):return 'server'
    if 'Backward' in name:return 'backward'
    if name.startswith('Init') or name=='BuildLstmLayerParams':return 'init'
    if 'Augment' in name or name in ['MyAffine','FindPerspectiveCoeffs','PerspectiveJitterPoints']:return 'augment'
    if mod=='train.py':return 'dataset'
    return 'checkpoint'

